                m.x["el-r"] * el_yield == Ca * 0.053
            )  # 53 kWh produced per ton of sugarcane processes

        m.el_produced = pyo.Constraint(rule=el_prod)

        def el_sales(m):
            return m.x["fre"] + m.x["reg"] == m.x["el-r"] * el_yield

        m.electricity = pyo.Constraint(rule=el_sales)

        # Expected Profit
        def profit(m, q):
            return m.profit[q] == sug_yield * m.x["sug"] * hp[
                q, "sug"
            ] + eth_yield * m.x["eth"] * hp[q, "eth"] + m.x["fre"] * hp[q, "fre"] + m.x[
                "reg"
            ] * price_reg - sum(
                m.x[j] * prodcost[j] for j in m.saleable_products
            )

        m.profiteq = pyo.Constraint(m.price_time_obs, rule=profit)

        def eprofit1(m):
            return m.EP == (1 / N) * sum(m.profit[q] for q in m.price_time_obs)

        m.ep1 = pyo.Constraint(rule=eprofit1)

        # Product Revenues to be used in analysis
        def sug_prof(m):
            return sum(m.x["sug"] * hp[q, "sug"] for q in m.price_time_obs) * (1 / N)

        m.avg_sug_prof = pyo.Expression(rule=sug_prof)

        def eth_prof(m):
            return sum(m.x["eth"] * hp[q, "eth"] for q in m.price_time_obs) * (1 / N)

        m.avg_eth_prof = pyo.Expression(rule=eth_prof)

        def el_prof(m):
            return sum(m.x["fre"] * hp[q, "fre"] for q in m.price_time_obs) * (1 / N)

        m.avg_el_prof = pyo.Expression(rule=el_prof)
    elif mode == "stoc":
        reg_sugar_limit = 150000
        reg_eth_limit = 120000
        yield_range = (0.6, 1.4)
        mean_yield = 1
        m.SugarYieldSample = pyo.Var(
            domain=pyo.Reals, bounds=yield_range, initialize=mean_yield
        )

        # PYOMO SETS
        m.resources = pyo.Set(initialize=resources)
        m.saleable_products = pyo.Set(initialize=saleable_products)
        m.processes = pyo.Set(initialize=processes)
        m.price_time_obs = pyo.Set(initialize=q)
        m.commodities = pyo.Set(initialize=commodity)

        m.N = pyo.Param(initialize=N)
        m.r = pyo.Var(m.resources, m.processes, domain=pyo.NonNegativeReals)
        # VARIABLES
        # Positive Variables
        # First-Stage Decision Variables (Scenario-independent)
        m.x_bag = pyo.Var(domain=pyo.UnitInterval)  # Quantity of bagasse
        m.x_jui = pyo.Var(domain=pyo.UnitInterval)

        m.x_juiF = pyo.Var(domain=pyo.UnitInterval)
        m.x_juiD = pyo.Var(domain=pyo.UnitInterval)
        m.profit = pyo.Var(m.price_time_obs)
        m.EP1 = pyo.Var()
        m.EP = pyo.Var()

        initial_price_reg_sug = 800
        initial_price_reg_eth = 770
        price_reg_el = 72.5
        m.price_reg_sug = pyo.Param(
            m.price_time_obs,
            initialize=initial_price_reg_sug,
            domain=pyo.NonNegativeReals,
        )
        m.price_reg_eth = pyo.Param(
            m.price_time_obs,
            initialize=initial_price_reg_eth,
            domain=pyo.NonNegativeReals,
        )

        m.costs = pyo.Var(domain=pyo.NonNegativeReals)
        m.q_sugar_reg = pyo.Var(
            domain=pyo.NonNegativeReals
        )  # Sugar to regulated market
        m.q_sugar_free = pyo.Var(domain=pyo.NonNegativeReals)  # Sugar to free market
        m.q_eth_reg = pyo.Var(
            domain=pyo.NonNegativeReals
        )  # Ethanol to regulated market
        m.q_eth_free = pyo.Var(domain=pyo.NonNegativeReals)  # Ethanol to free market
        m.q_el_reg = pyo.Var(
            domain=pyo.NonNegativeReals
        )  # Electricity to regulated market
        m.q_el_free = pyo.Var(domain=pyo.NonNegativeReals)  # Electricity to free market
        m.q_mol = pyo.Var(domain=pyo.NonNegativeReals)  # Molasses produced

        # CONSTRAINTS
        # Superstructure

        def CoP(m):
            return m.costs == (
                (m.q_sugar_free + m.q_sugar_reg) * prodcost["sug"]
                + (m.q_eth_free + m.q_eth_reg) * prodcost["eth"]
                + (m.q_el_free + m.q_el_reg) * prodcost["fre"]
            )

